1	package chainledger
2	
3	import (
4		"reflect"
5		"slices"
6		"strings"
7		"testing"
8	)
9	
10	func mustRegister(t *testing.T, graph map[string]*Lineage, name string, parents ...string) {
11		t.Helper()
12		if err := Register(graph, Dataset{Name: name}, parents); err != nil {
13			t.Fatalf("Register(%s, %v): %v", name, parents, err)
14		}
15	}
16	
17	func sameStrings(got, want []string) bool {
18		if len(got) != len(want) {
19			return false
20		}
21		for i := range got {
22			if got[i] != want[i] {
23				return false
24			}
25		}
26		return true
27	}
28	
29	func assertEntry(t *testing.T, graph map[string]*Lineage, name string, wantParents, wantChildren []string) {
30		t.Helper()
31		entry, ok := graph[name]
32		if !ok {
33			t.Fatalf("dataset %q missing from graph", name)
34		}
35		if !sameStrings(entry.Parents, wantParents) {
36			t.Errorf("%s parents = %v, want %v", name, entry.Parents, wantParents)
37		}
38		if !sameStrings(entry.Children, wantChildren) {
39			t.Errorf("%s children = %v, want %v", name, entry.Children, wantChildren)
40		}
41	}
42	
43	// Every parent edge must be mirrored by exactly one matching child edge.
44	func assertConsistent(t *testing.T, graph map[string]*Lineage) {
45		t.Helper()
46		for name, entry := range graph {
47			counts := map[string]int{}
48			for _, c := range entry.Children {
49				counts[c]++
50				child, ok := graph[c]
51				if !ok {
52					t.Errorf("%s lists unknown child %s", name, c)
53					continue
54				}
55				if !slices.Contains(child.Parents, name) {
56					t.Errorf("%s is child of %s but has no matching parent edge", c, name)
57				}
58			}
59			for c, n := range counts {
60				if n != 1 {
61					t.Errorf("%s lists child %s %d times", name, c, n)
62				}
63			}
64			for _, p := range entry.Parents {
65				parent, ok := graph[p]
66				if !ok {
67					t.Errorf("%s lists unknown parent %s", name, p)
68					continue
69				}
70				if !slices.Contains(parent.Children, name) {
71					t.Errorf("%s is parent of %s but has no matching child edge", p, name)
72				}
73			}
74		}
75	}
76	
77	func TestRegisterBasicChainAndConsistency(t *testing.T) {
78		graph := map[string]*Lineage{}
79		mustRegister(t, graph, "raw")
80		mustRegister(t, graph, "detail", "raw")
81		mustRegister(t, graph, "summary", "detail")
82	
83		assertEntry(t, graph, "raw", nil, []string{"detail"})
84		assertEntry(t, graph, "detail", []string{"raw"}, []string{"summary"})
85		assertEntry(t, graph, "summary", []string{"detail"}, nil)
86		assertConsistent(t, graph)
87	
88		if got, want := Roots(graph), []string{"raw"}; !reflect.DeepEqual(got, want) {
89			t.Errorf("Roots = %v, want %v", got, want)
90		}
91	}
92	
93	// The scenario from the spec: re-registering detail while still using raw must
94	// succeed even though raw is detail's existing upstream.
95	func TestReregisterKeepsExistingUpstream(t *testing.T) {
96		graph := map[string]*Lineage{}
97		mustRegister(t, graph, "raw")
98		mustRegister(t, graph, "detail", "raw")
99		mustRegister(t, graph, "summary", "detail")
100	
101		mustRegister(t, graph, "detail", "raw")
102		assertEntry(t, graph, "raw", nil, []string{"detail"})
103		assertEntry(t, graph, "detail", []string{"raw"}, []string{"summary"})
104		assertEntry(t, graph, "summary", []string{"detail"}, nil)
105		assertConsistent(t, graph)
106	
107		// Same registration again: still successful, nothing changes.
108		before := snapshot(graph)
109		mustRegister(t, graph, "detail", "raw")
110		if !reflect.DeepEqual(snapshot(graph), before) {
111			t.Fatalf("identical re-registration changed graph: before=%v after=%v", before, snapshot(graph))
112		}
113	}
114	
115	// Pointing raw at summary closes raw -> summary -> detail -> raw.
116	func TestCycleAcrossMultipleLevelsRejected(t *testing.T) {
117		graph := map[string]*Lineage{}
118		mustRegister(t, graph, "raw")
119		mustRegister(t, graph, "detail", "raw")
120		mustRegister(t, graph, "summary", "detail")
121	
122		before := snapshot(graph)
123		err := Register(graph, Dataset{Name: "raw"}, []string{"summary"})
124		if err == nil {
125			t.Fatal("expected cycle error, got nil")
126		}
127		if !strings.Contains(err.Error(), "cycle") || !strings.Contains(err.Error(), "summary") {
128			t.Errorf("error %q should mention a cycle and the related name summary", err.Error())
129		}
130		if !reflect.DeepEqual(snapshot(graph), before) {
131			t.Fatalf("failed registration changed graph: before=%v after=%v", before, snapshot(graph))
132		}
133		assertEntry(t, graph, "raw", nil, []string{"detail"})
134		assertConsistent(t, graph)
135	}
136	
137	// Multiple upstreams plus a diamond shape are legitimate and must not look like
138	// a cycle, while a genuinely cyclic multi-parent request is refused.
139	func TestMultipleUpstreamsAndDiamond(t *testing.T) {
140		graph := map[string]*Lineage{}
141		mustRegister(t, graph, "x")
142		mustRegister(t, graph, "y")
143		mustRegister(t, graph, "a", "x")
144		mustRegister(t, graph, "b", "x", "y")
145		mustRegister(t, graph, "d", "a", "b")
146		assertConsistent(t, graph)
147		assertEntry(t, graph, "x", nil, []string{"a", "b"})
148		assertEntry(t, graph, "y", nil, []string{"b"})
149		assertEntry(t, graph, "d", []string{"a", "b"}, nil)
150	
151		// x -> d closes through both a and b, several levels deep.
152		before := snapshot(graph)
153		if err := Register(graph, Dataset{Name: "x"}, []string{"d"}); err == nil {
154			t.Fatal("expected transitive cycle through diamond to be rejected")
155		} else if !strings.Contains(err.Error(), "d") {
156			t.Errorf("error %q should name parent d", err.Error())
157		}
158		if !reflect.DeepEqual(snapshot(graph), before) {
159			t.Fatal("failed cycle registration mutated the graph")
160		}
161	
162		// Direct mutual reference is the simple case and must also fail.
163		if err := Register(graph, Dataset{Name: "a"}, []string{"d"}); err == nil {
164			t.Fatal("expected direct mutual-reference cycle to be rejected")
165		}
166		assertConsistent(t, graph)
167	}
168	
169	// Replacing upstreams: old ones lose the reverse edge, new ones gain it at the
170	// end, retained ones keep a single entry in place; own children survive.
171	func TestReregisterReplacesUpstreamsKeepsDownstreams(t *testing.T) {
172		graph := map[string]*Lineage{}
173		mustRegister(t, graph, "old1")
174		mustRegister(t, graph, "old2")
175		mustRegister(t, graph, "keep")
176		mustRegister(t, graph, "new1")
177		mustRegister(t, graph, "new2")
178		mustRegister(t, graph, "center", "old1", "keep", "old2")
179		// Existing children in a fixed order, with another unrelated child interleaved.
180		mustRegister(t, graph, "childX", "center", "keep")
181		mustRegister(t, graph, "childY", "center")
182	
183		mustRegister(t, graph, "center", "keep", "new1", "new2")
184	
185		assertEntry(t, graph, "center",
186			[]string{"keep", "new1", "new2"},
187			[]string{"childX", "childY"})
188		assertEntry(t, graph, "old1", nil, nil)
189		assertEntry(t, graph, "old2", nil, nil)
190		assertEntry(t, graph, "keep", nil, []string{"center", "childX"})
191		assertEntry(t, graph, "new1", nil, []string{"center"})
192		assertEntry(t, graph, "new2", nil, []string{"center"})
193		assertConsistent(t, graph)
194	}
195	
196	// Duplicate parent names collapse to one entry, first occurrence wins, and the
197	// declared list order is the stored order.
198	func TestDuplicateUpstreamsDedupedFirstWins(t *testing.T) {
199		graph := map[string]*Lineage{}
200		mustRegister(t, graph, "a")
201		mustRegister(t, graph, "b")
202		mustRegister(t, graph, "c")
203		mustRegister(t, graph, "d", "b", "a", "b", "c", "a")
204	
205		assertEntry(t, graph, "d", []string{"b", "a", "c"}, nil)
206		assertEntry(t, graph, "a", nil, []string{"d"})
207		assertEntry(t, graph, "b", nil, []string{"d"})
208		assertEntry(t, graph, "c", nil, []string{"d"})
209		assertConsistent(t, graph)
210	
211		// Re-registering with duplicates is repeatedly idempotent.
212		before := snapshot(graph)
213		mustRegister(t, graph, "d", "b", "a", "b", "c", "a")
214		mustRegister(t, graph, "d", "b", "a", "b", "c", "a")
215		if !reflect.DeepEqual(snapshot(graph), before) {
216			t.Fatal("idempotent re-registration changed the graph")
217		}
218	}
219	
220	// New children land at the end of an upstream's child list; existing relative
221	// order is untouched.
222	func TestNewDownstreamAppendedAtEnd(t *testing.T) {
223		graph := map[string]*Lineage{}
224		mustRegister(t, graph, "p")
225		mustRegister(t, graph, "first", "p")
226		mustRegister(t, graph, "second", "p")
227	
228		mustRegister(t, graph, "late", "p")
229		assertEntry(t, graph, "p", nil, []string{"first", "second", "late"})
230	
231		// Re-registering first must not move it.
232		mustRegister(t, graph, "first", "p")
233		assertEntry(t, graph, "p", nil, []string{"first", "second", "late"})
234		assertConsistent(t, graph)
235	}
236	
237	// Empty upstream list turns the dataset into a root: reverse edges removed,
238	// downstreams retained; Roots updates and stays name-sorted.
239	func TestEmptyUpstreamsBecomesRoot(t *testing.T) {
240		graph := map[string]*Lineage{}
241		mustRegister(t, graph, "raw")
242		mustRegister(t, graph, "other")
243		mustRegister(t, graph, "mid", "raw", "other")
244		mustRegister(t, graph, "leaf", "mid")
245	
246		mustRegister(t, graph, "mid") // no upstreams now
247		assertEntry(t, graph, "mid", nil, []string{"leaf"})
248		assertEntry(t, graph, "raw", nil, nil)
249		assertEntry(t, graph, "other", nil, nil)
250		assertEntry(t, graph, "leaf", []string{"mid"}, nil)
251		assertConsistent(t, graph)
252	
253		if got, want := Roots(graph), []string{"mid", "other", "raw"}; !reflect.DeepEqual(got, want) {
254			t.Errorf("Roots = %v, want %v", got, want)
255		}
256	}
257	
258	// A failure partway through the list leaves no new node and no partial reverse
259	// edges, even when a valid parent precedes the offending one.
260	func TestFailureIsAtomicWithValidParentFirst(t *testing.T) {
261		graph := map[string]*Lineage{}
262		mustRegister(t, graph, "p")
263		mustRegister(t, graph, "p2")
264		mustRegister(t, graph, "existing", "p")
265		before := snapshot(graph)
266	
267		err := Register(graph, Dataset{Name: "newkid"}, []string{"p", "ghost"})
268		if err == nil || !strings.Contains(err.Error(), "ghost") {
269			t.Fatalf("want unknown-parent error naming ghost, got %v", err)
270		}
271		if _, ok := graph["newkid"]; ok {
272			t.Error("failed registration left new node newkid in graph")
273		}
274		if !reflect.DeepEqual(snapshot(graph), before) {
275			t.Fatalf("graph changed after failure: before=%v after=%v", before, snapshot(graph))
276		}
277		assertEntry(t, graph, "p", nil, []string{"existing"})
278		assertConsistent(t, graph)
279	
280		// Self reference after a valid parent is likewise atomic.
281		err = Register(graph, Dataset{Name: "loop"}, []string{"p2", "loop"})
282		if err == nil || !strings.Contains(err.Error(), "its own parent") {
283			t.Fatalf("want self-parent error, got %v", err)
284		}
285		if _, ok := graph["loop"]; ok {
286			t.Error("failed self-parent registration left node in graph")
287		}
288		if !reflect.DeepEqual(snapshot(graph), before) {
289			t.Fatalf("graph changed after self-parent failure")
290		}
291	
292		// After fixing the request, the dataset registers normally.
293		mustRegister(t, graph, "newkid", "p", "p2")
294		assertEntry(t, graph, "newkid", []string{"p", "p2"}, nil)
295		assertConsistent(t, graph)
296	}
297	
298	// Rejected re-registration of an existing node preserves its old content and
299	// every other node.
300	func TestFailedReregisterPreservesOldEdges(t *testing.T) {
301		graph := map[string]*Lineage{}
302		mustRegister(t, graph, "raw")
303		mustRegister(t, graph, "mid", "raw")
304		mustRegister(t, graph, "top", "mid")
305		before := snapshot(graph)
306	
307		if err := Register(graph, Dataset{Name: "mid"}, []string{"top"}); err == nil {
308			t.Fatal("expected cycle rejection on re-register")
309		}
310		if !reflect.DeepEqual(snapshot(graph), before) {
311			t.Fatalf("failed re-registration changed graph: before=%v after=%v", before, snapshot(graph))
312		}
313	
314		if err := Register(graph, Dataset{Name: "mid"}, []string{"missing"}); err == nil {
315			t.Fatal("expected unknown-parent rejection on re-register")
316		}
317		if !reflect.DeepEqual(snapshot(graph), before) {
318			t.Fatalf("failed re-registration changed graph: before=%v after=%v", before, snapshot(graph))
319		}
320		assertConsistent(t, graph)
321	}
